"use client";
import id1 from '@/assets/id-1.avif';
import id2 from '@/assets/id-2.avif';
import id3 from '@/assets/id-3.avif';
import id4 from '@/assets/id-4.avif';
import id5 from '@/assets/id-5.avif';
const projects = [
  {
    id: 1,
    title: "E-Commerce Platform Redesign",
    category: "Web Development",
    description: "A complete overhaul of a high-traffic e-commerce store focusing on conversion rate optimization and headless architecture.",
    image: id1.src || id1,
  },
  {
    id: 2,
    title: "Fintech Dashboard UI",
    category: "SEO & Analytics",
    description: "Sleek, dark-mode analytics dashboard for a leading financial technology startup.",
    image: id2.src || id2,
  },
  {
    id: 3,
    title: "Corporate Identity App",
    category: "AI Automation",
    description: "Cross-platform mobile and web application streamlining internal communications for a Fortune 500 company.",
    image: id3.src || id3,
  },
  {
    id: 4,
    title: "AI Healthcare Portal",
    category: "Web Application",
    description: "Secure and intuitive patient portal integrating advanced AI diagnostics with a clean interface.",
    image: id4.src || id4,
  },
];

export default function PortfolioSection() {
  return (
    <section className="relative w-full bg-navy-muted overflow-hidden py-section-gap" id="portfolio" aria-labelledby="portfolio-title">
      {/* Background image overlay — same pattern as HeroSection */}
      <img
        src={id5.src || id5}
        alt=""
        aria-hidden="true"
        className="absolute inset-0 w-full h-full object-cover object-center opacity-10 mix-blend-luminosity"
        loading="lazy"
      />
      <div className="absolute inset-0 bg-gradient-to-b from-navy-muted via-navy-muted/95 to-navy-muted"></div>

      <div className="relative z-10 max-w-[1280px] mx-auto px-margin-mobile md:px-margin-desktop">

        {/* Header — mirrors HeroSection left-border accent */}
        <div className="flex flex-col gap-4 max-w-3xl border-l-2 border-champagne-light pl-4 sm:pl-gutter py-2 mb-8 md:mb-12">
          <span className="font-label-caps text-xs text-champagne-light tracking-widest uppercase font-bold">Our Work</span>
          <h2 id="portfolio-title" className="font-headline-lg text-2xl sm:text-3xl md:text-4xl text-surface font-bold">Featured Projects</h2>
          <p className="font-body-md text-sm sm:text-base text-slate-200 max-w-xl leading-relaxed font-medium">
            We partner with forward-thinking brands to create digital experiences that merge stunning aesthetics with powerful technical execution.
          </p>
        </div>

        {/* Project Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
          {projects.map((project) => (
            <div
              key={project.id}
              className="group relative overflow-hidden rounded-none bg-navy-dark/50 backdrop-blur-sm border border-outline-variant/30 transition-all duration-500 hover:border-champagne-light/50 cursor-pointer shadow-lg"
            >
              <div className="relative h-[220px] sm:h-[280px] md:h-[340px] overflow-hidden">
                <div className="absolute inset-0 bg-gradient-to-t from-navy-dark via-navy-dark/60 to-transparent z-10 opacity-80 group-hover:opacity-60 transition-opacity duration-500"></div>
                <img
                  src={project.image}
                  alt={`Preview of ${project.title}`}
                  className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
                  loading="lazy"
                  width="800"
                  height="600"
                />
              </div>

              <div className="absolute bottom-0 left-0 w-full p-5 sm:p-6 md:p-8 z-20 transform translate-y-2 group-hover:translate-y-0 transition-transform duration-500">
                <span className="inline-block font-label-caps text-[10px] sm:text-[11px] uppercase tracking-widest text-champagne-light mb-2 bg-navy-dark/80 backdrop-blur-md px-3 py-1 border border-champagne-light/30 font-bold">
                  {project.category}
                </span>
                <h3 className="font-headline-md text-xl sm:text-[22px] md:text-[26px] text-surface font-bold mb-1">
                  {project.title}
                </h3>
                <p className="font-body-md text-xs sm:text-sm text-slate-200 opacity-90 sm:opacity-0 group-hover:opacity-100 transition-opacity duration-500 delay-100 line-clamp-2 font-medium">
                  {project.description}
                </p>
              </div>
            </div>
          ))}
        </div>

        {/* CTA */}
        <div className="mt-8 md:mt-12 flex flex-col sm:flex-row gap-3 sm:gap-4 sm:pl-gutter w-full sm:w-auto">
          <a href="/#contact" className="bg-champagne-light text-navy-muted font-label-caps uppercase tracking-widest text-xs px-6 py-3.5 rounded-none hover:bg-white transition-all shadow-lg border border-champagne-light text-center font-bold">
            Start Your Project
          </a>
          <a href="/#services" className="bg-transparent border border-outline-variant text-slate-200 font-label-caps uppercase tracking-widest text-xs px-6 py-3.5 rounded-none hover:text-champagne-light hover:border-champagne-light transition-all text-center font-bold">
            Our Services
          </a>
        </div>

      </div>
    </section>
  );
}
